      const hits = rows.filter(([id, state]) => {
        if (HeatpumpFlowCard._fit(rule.kind, id, state).verdict === 'bad') return false;
        return [...hfcAssistantNames(id, hass.entities[id], state)].some((name) => wanted.has(name));
      });
