  _sumComplete(key) { return !this._sums?.[key] || this._sums[key].every((id) => Number.isFinite(hfcPowerW(this._hass?.states[id]))); }
  _unit(key) { return String(this._st(key)?.attributes?.unit_of_measurement || '').toLowerCase(); }
